#include <iostream>
#include <string>

int main() {
    std::string text;
    std::getline(std::cin, text);
    for (size_t index = 1; index + 2 < text.length(); ++index) {
        if (text[index] == 'a' && text[index + 1] == 't') {
            text = text.substr(0, index) + '@' + text.substr(index + 2);
            break;
        }
    }
    size_t counter = 1;
    while (counter + 2 < text.length() - 1) {
        if (text[counter] == 'd' && text[counter + 1] == 'o' && text[counter + 2] == 't') {
            text = text.substr(0, counter) + '.' + text.substr(counter + 3);
        }
        ++counter;
    }
    std::cout << text << std::endl;
    return 0;
}
